1	import { requireAreaOrGrant } from "@/lib/staff-grants";
2	import { SupportTicketView } from "@/components/admin/SupportTicketView";
3	
4	export const dynamic = "force-dynamic";
5	
6	export default async function AdminTicket({ params }: { params: Promise<{ id: string }> }) {
7	  const adminUser = await requireAreaOrGrant("supportTickets");
8	  const { id } = await params;
9	  return <SupportTicketView id={id} currentUserId={adminUser.id} portal="admin" />;
10	}
