1	"use client";
2	
3	import {
4	  useCallback,
5	  useEffect,
6	  useRef,
7	  useState,
8	  useTransition,
9	  type ClipboardEvent,
10	} from "react";
11	import { LightboxImage } from "@/components/ui/LightboxImage";
12	import {
13	  listConversations,
14	  replyToConversation,
15	  replyWithAttachment,
16	  closeConversation,
17	  closeAllConversations,
18	  assignConversation,
19	  signalAgentTyping,
20	  toggleAiPaused,
21	  transferChatToTicket,
22	} from "@/lib/actions-chat";
23	import { useVoiceDictation } from "@/components/customer/claude-code/voice";
24	import { CannedReplyPicker } from "@/components/support/CannedReplyPicker";
25	
26	/**
27	 * Admin live-chat inbox. Two-pane layout: a conversation list (unread + newest
28	 * first) and a thread view with a reply box. Polls `listConversations` every
29	 * few seconds so new visitor messages appear without a manual refresh.
30	 */
31	
32	type Attachment = { id: string; mime: string; sizeBytes: number };
33	type Msg = {
34	  id: string;
35	  sender: string;
36	  body: string;
37	  createdAt: string;
38	  attachment?: Attachment | null;
39	};
40	type Convo = {
41	  id: string;
42	  visitorId: string;
43	  userId: string | null;
44	  name: string | null;
45	  email: string | null;
46	  status: string;
47	  assignedToId: string | null;
48	  assignedToName: string | null;
49	  unreadForAgent: boolean;
50	  lastMessageAt: string;
51	  createdAt: string;
52	  visitorTyping: boolean;
53	  aiPaused: boolean;
54	  messages: Msg[];
55	};
56	
57	/** Three-dot "typing…" pulse, matching the widget's indicator. */
58	function TypingDots() {
59	  return (
60	    <span className="flex items-center gap-1" aria-hidden="true">
61	      {[0, 150, 300].map((delay) => (
62	        <span
63	          key={delay}
64	          className="h-1.5 w-1.5 animate-pulse rounded-full bg-brand-300"
65	          style={{ animationDelay: `${delay}ms`, animationDuration: "1s" }}
66	        />
67	      ))}
68	    </span>
69	  );
70	}
71	
72	/** Small robot glyph used to mark AI-assistant messages, matching the widget. */
73	function BotIcon({ className = "" }: { className?: string }) {
74	  return (
75	    <svg
76	      width="11"
77	      height="11"
78	      viewBox="0 0 24 24"
79	      fill="none"
80	      stroke="currentColor"
81	      strokeWidth="2"
82	      strokeLinecap="round"
83	      strokeLinejoin="round"
84	      className={className}
85	      aria-hidden
86	    >
87	      <path d="M12 2v3M5 8h14a1 1 0 0 1 1 1v9a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V9a1 1 0 0 1 1-1zM9 13h.01M15 13h.01" />
88	    </svg>
89	  );
90	}
91	
92	const POLL_MS = 5000;
93	
94	// Client-side pre-checks only; replyWithAttachment re-validates by signature.
95	const ACCEPT_IMAGES = "image/png,image/jpeg,image/gif,image/webp";
96	const ALLOWED_IMAGE_TYPES = new Set(["image/png", "image/jpeg", "image/gif", "image/webp"]);
97	const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
98	
99	function imageError(file: File): string | null {
100	  if (!ALLOWED_IMAGE_TYPES.has(file.type)) return "Only PNG, JPEG, GIF, or WEBP images.";
101	  if (file.size > MAX_IMAGE_BYTES) return "Image must be 5 MB or smaller.";
102	  return null;
103	}
104	
105	function timeAgo(iso: string): string {
106	  const s = Math.floor((Date.now() - new Date(iso).getTime()) / 1000);
107	  if (s < 60) return `${s}s ago`;
108	  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
109	  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
110	  return `${Math.floor(s / 86400)}d ago`;
111	}
112	
113	export default function ChatInbox({ initial }: { initial: Convo[] }) {
114	  const [convos, setConvos] = useState<Convo[]>(initial);
115	  const [selectedId, setSelectedId] = useState<string | null>(initial[0]?.id ?? null);
116	  const [draft, setDraft] = useState("");
117	  const [query, setQuery] = useState("");
118	  const [error, setError] = useState("");
119	  const [pendingImage, setPendingImage] = useState<{ file: File; url: string } | null>(null);
120	  const [pending, start] = useTransition();
121	  const scrollRef = useRef<HTMLDivElement>(null);
122	  const fileInputRef = useRef<HTMLInputElement>(null);
123	  const lastTypingPingRef = useRef(0); // throttle "agent is typing" pings
124	  // Mic-to-text for the reply box — same Web Speech hook the Kodely build
125	  // console uses (components/customer/claude-code/voice.tsx); feature-detects
126	  // and the button below simply doesn't render when unsupported (e.g. Firefox).
127	  const voice = useVoiceDictation(setDraft);
128	
129	  useEffect(() => {
130	    return () => {
131	      if (pendingImage) URL.revokeObjectURL(pendingImage.url);
132	    };
133	  }, [pendingImage]);
134	
135	  useEffect(() => {
136	    if (voice.error) setError(voice.error);
137	  }, [voice.error]);
138	
139	  function pickImage(file: File | null | undefined) {
140	    if (!file) return;
141	    const err = imageError(file);
142	    if (err) {
143	      setError(err);
144	      return;
145	    }
146	    setError("");
147	    setPendingImage((prev) => {
148	      if (prev) URL.revokeObjectURL(prev.url);
149	      return { file, url: URL.createObjectURL(file) };
150	    });
151	  }
152	
153	  function clearImage() {
154	    setPendingImage((prev) => {
155	      if (prev) URL.revokeObjectURL(prev.url);
156	      return null;
157	    });
158	    if (fileInputRef.current) fileInputRef.current.value = "";
159	  }
160	
161	  function onPaste(e: ClipboardEvent) {
162	    const item = Array.from(e.clipboardData?.items ?? []).find((i) =>
163	      i.type.startsWith("image/")
164	    );
165	    if (item) {
166	      const file = item.getAsFile();
167	      if (file) {
168	        e.preventDefault();
169	        pickImage(file);
170	      }
171	    }
172	  }
173	
174	  const refresh = useCallback(async () => {
175	    try {
176	      const rows = await listConversations();
177	      setConvos(rows);
178	    } catch {
179	      /* transient — next poll retries */
180	    }
181	  }, []);
182	
183	  useEffect(() => {
184	    const t = setInterval(refresh, POLL_MS);
185	    return () => clearInterval(t);
186	  }, [refresh]);
187	
188	  const selected = convos.find((c) => c.id === selectedId) ?? null;
189	
190	  // Tell the visitor's widget this agent is composing, throttled to ~once/2.5s.
191	  function pingTyping() {
192	    if (!selectedId) return;
193	    const now = Date.now();
194	    if (now - lastTypingPingRef.current < 2500) return;
195	    lastTypingPingRef.current = now;
196	    void signalAgentTyping(selectedId);
197	  }
198	
199	  useEffect(() => {
200	    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight });
201	  }, [selected?.messages.length, selectedId]);
202	
203	  function doReply() {
204	    if (!selected || pending) return;
205	    if (!draft.trim() && !pendingImage) return;
206	    const body = draft;
207	    setError("");
208	
209	    if (pendingImage) {
210	      const fd = new FormData();
211	      fd.append("conversationId", selected.id);
212	      fd.append("file", pendingImage.file);
213	      if (body.trim()) fd.append("body", body.trim());
214	      start(async () => {
215	        const res = await replyWithAttachment(fd);
216	        if (res.error) {
217	          setError(res.error);
218	          return;
219	        }
220	        setDraft("");
221	        clearImage();
222	        await refresh();
223	      });
224	      return;
225	    }
226	
227	    start(async () => {
228	      const res = await replyToConversation(selected.id, body);
229	      if (res.error) {
230	        setError(res.error);
231	        return;
232	      }
233	      setDraft("");
234	      await refresh();
235	    });
236	  }
237	
238	  function doClose() {
239	    if (!selected) return;
240	    start(async () => {
241	      await closeConversation(selected.id);
242	      await refresh();
243	    });
244	  }
245	
246	  function doCloseAll() {
247	    const openCount = convos.filter((c) => c.status !== "CLOSED").length;
248	    if (openCount === 0 || pending) return;
249	    if (
250	      typeof window !== "undefined" &&
251	      !window.confirm(`Close all ${openCount} open conversation${openCount === 1 ? "" : "s"}?`)
252	    ) {
253	      return;
254	    }
255	    start(async () => {
256	      await closeAllConversations();
257	      await refresh();
258	    });
259	  }
260	
261	  function doAssign() {
262	    if (!selected) return;
263	    start(async () => {
264	      await assignConversation(selected.id);
265	      await refresh();
266	    });
267	  }
268	
269	  function doToggleAi() {
270	    if (!selected || pending) return;
271	    start(async () => {
272	      const res = await toggleAiPaused(selected.id);
273	      if (res.error) {
274	        setError(res.error);
275	        return;
276	      }
277	      await refresh();
278	    });
279	  }
280	
281	  function doTransfer() {
282	    if (!selected || pending) return;
283	    if (
284	      typeof window !== "undefined" &&
285	      !window.confirm("Transfer this conversation to a support ticket? The chat will be closed.")
286	    ) {
287	      return;
288	    }
289	    setError("");
290	    start(async () => {
291	      const res = await transferChatToTicket(selected.id);
292	      // A successful transfer redirects server-side and never returns here —
293	      // reaching this line means it was refused (e.g. no linked customer account).
294	      if (res?.error) setError(res.error);
295	    });
296	  }
297	
298	  function label(c: Convo): string {
299	    return c.name || c.email || `Visitor ${c.visitorId.slice(0, 8)}`;
300	  }
301	
302	  // Who authored a given message, from the staff perspective. The bot ("bot") is
303	  // always the AI assistant; a human reply ("agent") is attributed to the agent
304	  // handling the thread (assignedToName), or a generic "Support agent" fallback.
305	  function messageAuthor(c: Convo, m: Msg): string {
306	    if (m.sender === "bot") return "Nxeon Assistant · AI";
307	    if (m.sender === "agent") return c.assignedToName || "Support agent";
308	    return label(c);
309	  }
310	
311	  // One-line preview of the last message for the list, prefixed by who sent it.
312	  function lastPreview(c: Convo): string {
313	    const last = c.messages[c.messages.length - 1];
314	    if (!last) return "…";
315	    const body = last.body || (last.attachment ? "📎 image" : "");
316	    if (last.sender === "agent") return `You: ${body}`;
317	    if (last.sender === "bot") return `AI: ${body}`;
318	    return body;
319	  }
320	
321	  const q = query.trim().toLowerCase();
322	  const filtered = q
323	    ? convos.filter((c) => {
324	        const haystack = [
325	          c.name,
326	          c.email,
327	          c.visitorId,
328	          c.assignedToName,
329	          ...c.messages.map((m) => m.body),
330	        ]
331	          .filter(Boolean)
332	          .join(" ")
333	          .toLowerCase();
334	        return haystack.includes(q);
335	      })
336	    : convos;
337	
338	  const openCount = convos.filter((c) => c.status !== "CLOSED").length;
339	
340	  return (
341	    <div className="grid gap-4 lg:grid-cols-[20rem_1fr]">
342	      {/* Conversation list */}
343	      <div className="card flex max-h-[70vh] flex-col p-0">
344	        {/* Toolbar: search + bulk close */}
345	        <div className="space-y-2 border-b border-white/10 p-2.5">
346	          <div className="relative">
347	            <svg
348	              width="15"
349	              height="15"
350	              viewBox="0 0 24 24"
351	              fill="none"
352	              stroke="currentColor"
353	              strokeWidth="2"
354	              strokeLinecap="round"
355	              strokeLinejoin="round"
356	              className="pointer-events-none absolute left-2.5 top-1/2 -translate-y-1/2 text-slate-500"
357	              aria-hidden
358	            >
359	              <circle cx="11" cy="11" r="7" />
360	              <path d="m21 21-4.3-4.3" />
361	            </svg>
362	            <input
363	              type="search"
364	              value={query}
365	              onChange={(e) => setQuery(e.target.value)}
366	              placeholder="Search name, email or message…"
367	              aria-label="Search conversations"
368	              className="input w-full py-1.5 pl-8 pr-2 text-xs"
369	            />
370	          </div>
371	          <div className="flex items-center justify-between gap-2 px-0.5">
372	            <span className="text-[11px] text-slate-500">
373	              {filtered.length === convos.length
374	                ? `${convos.length} conversation${convos.length === 1 ? "" : "s"}`
375	                : `${filtered.length} of ${convos.length}`}
376	            </span>
377	            <button
378	              type="button"
379	              onClick={doCloseAll}
380	              disabled={pending || openCount === 0}
381	              className="rounded-lg border border-white/10 px-2 py-0.5 text-[11px] text-slate-300 transition hover:bg-white/[0.06] disabled:opacity-40"
382	            >
383	              Close all{openCount > 0 ? ` (${openCount})` : ""}
384	            </button>
385	          </div>
386	        </div>
387	
388	        <div className="flex-1 space-y-1 overflow-y-auto p-2">
389	          {convos.length === 0 && (
390	            <p className="p-4 text-center text-sm text-slate-500">No conversations yet.</p>
391	          )}
392	          {convos.length > 0 && filtered.length === 0 && (
393	            <p className="p-4 text-center text-sm text-slate-500">No matches for “{query}”.</p>
394	          )}
395	          {filtered.map((c) => {
396	            const active = c.id === selectedId;
397	            const closed = c.status === "CLOSED";
398	            return (
399	              <button
400	                key={c.id}
401	                onClick={() => setSelectedId(c.id)}
402	                className={`w-full rounded-xl border px-3 py-2.5 text-left transition ${
403	                  active
404	                    ? "border-brand-500/50 bg-brand-500/10"
405	                    : "border-transparent hover:bg-white/[0.04]"
406	                }`}
407	              >
408	                <div className="flex items-center justify-between gap-2">
409	                  <span
410	                    className={`truncate text-sm font-medium ${
411	                      closed ? "text-slate-400" : "text-slate-100"
412	                    }`}
413	                  >
414	                    {label(c)}
415	                  </span>
416	                  <div className="flex shrink-0 items-center gap-1.5">
417	                    {c.unreadForAgent && !closed && (
418	                      <span
419	                        className="h-2 w-2 rounded-full bg-amber-400"
420	                        title="Needs a reply"
421	                      />
422	                    )}
423	                    {closed && (
424	                      <span className="rounded bg-white/[0.06] px-1.5 py-0.5 text-[9px] font-medium uppercase tracking-wide text-slate-500">
425	                        closed
426	                      </span>
427	                    )}
428	                  </div>
429	                </div>
430	                <div className="mt-0.5 flex items-center justify-between gap-2">
431	                  <span className="truncate text-xs text-slate-400">{lastPreview(c)}</span>
432	                  <span className="shrink-0 text-[10px] text-slate-500">
433	                    {timeAgo(c.lastMessageAt)}
434	                  </span>
435	                </div>
436	              </button>
437	            );
438	          })}
439	        </div>
440	      </div>
441	
442	      {/* Thread view */}
443	      <div className="card flex max-h-[70vh] flex-col p-0">
444	        {!selected ? (
445	          <div className="flex flex-1 items-center justify-center p-10 text-sm text-slate-500">
446	            Select a conversation to view it.
447	          </div>
448	        ) : (
449	          <>
450	            <div className="flex flex-wrap items-center justify-between gap-2 border-b border-white/10 px-4 py-3">
451	              <div>
452	                <p className="text-sm font-semibold text-slate-100">{label(selected)}</p>
453	                <p className="text-xs text-slate-400">
454	                  {selected.email || "no email"}
455	                  {selected.userId ? " · registered customer" : " · guest"} ·{" "}
456	                  {selected.status.toLowerCase()}
457	                  {selected.assignedToName ? ` · assigned to ${selected.assignedToName}` : ""}
458	                </p>
459	              </div>
460	              <div className="flex items-center gap-2">
461	                <button
462	                  type="button"
463	                  onClick={doToggleAi}
464	                  disabled={pending}
465	                  title={
466	                    selected.aiPaused
467	                      ? "The AI assistant is paused on this thread — click to resume it."
468	                      : "The AI assistant may answer this thread — click to pause it."
469	                  }
470	                  className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition disabled:opacity-50 ${
471	                    selected.aiPaused
472	                      ? "border-amber-400/30 bg-amber-500/10 text-amber-300 hover:bg-amber-500/20"
473	                      : "border-brand-400/30 bg-brand-500/10 text-brand-200 hover:bg-brand-500/20"
474	                  }`}
475	                >
476	                  {selected.aiPaused ? "AI: Paused" : "AI: On"}
477	                </button>
478	                <button
479	                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
480	                  onClick={doAssign}
481	                  disabled={pending}
482	                >
483	                  Assign to me
484	                </button>
485	                {selected.status !== "CLOSED" && (
486	                  <button
487	                    className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
488	                    onClick={doClose}
489	                    disabled={pending}
490	                  >
491	                    Close
492	                  </button>
493	                )}
494	                <button
495	                  className="rounded-lg border border-white/10 px-2.5 py-1 text-xs text-slate-300 hover:bg-white/[0.06] disabled:opacity-50"
496	                  onClick={doTransfer}
497	                  disabled={pending}
498	                  title="Copy this conversation into a new support ticket and close the chat."
499	                >
500	                  Transfer to ticket
501	                </button>
502	              </div>
503	            </div>
504	
505	            <div ref={scrollRef} className="flex-1 space-y-3 overflow-y-auto px-4 py-4">
506	              {selected.messages.map((m) => {
507	                const isCustomer = m.sender === "visitor";
508	                const isBot = m.sender === "bot";
509	                // Staff (human agent + AI bot) sit on the right, opposite the
510	                // customer, each with a distinct bubble and an author label.
511	                return (
512	                  <div
513	                    key={m.id}
514	                    className={`flex flex-col ${isCustomer ? "items-start" : "items-end"}`}
515	                  >
516	                    <span
517	                      className={`mb-0.5 flex items-center gap-1 px-1 text-[11px] font-medium ${
518	                        isBot ? "text-brand-300" : isCustomer ? "text-slate-400" : "text-brand-200"
519	                      }`}
520	                    >
521	                      {isBot && <BotIcon />}
522	                      {messageAuthor(selected, m)}
523	                    </span>
524	                    <div
525	                      className={`max-w-[75%] space-y-1.5 whitespace-pre-wrap rounded-2xl px-3.5 py-2 text-sm ${
526	                        isCustomer
527	                          ? "border border-white/10 bg-white/[0.06] text-slate-200"
528	                          : isBot
529	                            ? "border border-brand-400/30 bg-brand-500/10 text-slate-100"
530	                            : "bg-brand-500 text-white"
531	                      }`}
532	                    >
533	                      {m.attachment && (
534	                        <LightboxImage
535	                          src={`/api/chat/attachment/${m.attachment.id}`}
536	                          alt="attachment"
537	                          className="max-h-48 max-w-full rounded-lg border border-white/10 object-contain"
538	                        />
539	                      )}
540	                      {m.body && <div>{m.body}</div>}
541	                      <div
542	                        className={`mt-1 text-[10px] ${
543	                          isCustomer || isBot ? "text-slate-500" : "text-white/60"
544	                        }`}
545	                      >
546	                        {timeAgo(m.createdAt)}
547	                      </div>
548	                    </div>
549	                  </div>
550	                );
551	              })}
552	              {selected.visitorTyping && (
553	                <div className="flex justify-start" aria-live="polite">
554	                  <div className="flex items-center gap-2 rounded-2xl border border-white/10 bg-white/[0.06] px-3.5 py-2.5">
555	                    <TypingDots />
556	                    <span className="text-[11px] text-slate-400">{label(selected)} is typing…</span>
557	                  </div>
558	                </div>
559	              )}
560	            </div>
561	
562	            <div className="border-t border-white/10 px-4 py-3">
563	              {error && <p className="mb-2 text-xs text-red-400">{error}</p>}
564	              <div className="mb-2 flex justify-end">
565	                <CannedReplyPicker
566	                  disabled={pending}
567	                  onInsert={(snippet) => setDraft((prev) => (prev.trim() ? `${prev}\n\n${snippet}` : snippet))}
568	                />
569	              </div>
570	              {pendingImage && (
571	                <div className="mb-2 flex items-center gap-2">
572	                  <div className="relative">
573	                    {/* eslint-disable-next-line @next/next/no-img-element */}
574	                    <img
575	                      src={pendingImage.url}
576	                      alt="preview"
577	                      className="h-14 w-14 rounded-lg border border-white/10 object-cover"
578	                    />
579	                    <button
580	                      type="button"
581	                      aria-label="Remove image"
582	                      onClick={clearImage}
583	                      className="absolute -right-1.5 -top-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-slate-800 text-slate-200 ring-1 ring-white/20 hover:bg-slate-700"
584	                    >
585	                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
