import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { db } from "@/lib/db";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * READ-ONLY unread live-chat count for the admin browser notifier.
 *
 * GET /api/admin/chat-unread → { count } — the number of chat conversations
 * flagged `unreadForAgent` (the same "needs a reply" signal the chat inbox and
 * the sidebar badge count by). <AdminChatNotifier/> polls this while an admin
 * tab is open and beeps / fires a Web Notification when the count increases.
 *
 * Gated to support staff exactly like the inbox itself; never writes anything.
 */
export async function GET() {
  const user = await realUser();
  if (!user || !canAccess(user.role, "support")) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  // Fail soft to 0 so a transient DB hiccup never surfaces as a notifier error.
  const count = await db.chatConversation
    .count({ where: { unreadForAgent: true } })
    .catch(() => 0);

  return NextResponse.json({ count }, { headers: NO_STORE_HEADERS });
}
