import { getMonitorFeed } from "@/lib/monitor-feed";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * GET /api/admin/monitor-feed → the live-ops feed for /admin/monitor.
 *
 * Polled client-side by <LiveMonitorTerminal/> to drive the console view
 * without a full page navigation. Read-only, `fleet`-gated (ADMIN only, same
 * as every other fleet page) exactly like the SSR page it backs — a hand-typed
 * fetch from a non-admin session gets a 401, not a data leak.
 */
export async function GET() {
  const user = await realUser();
  if (!user || !canAccess(user.role, "fleet")) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  try {
    const feed = await getMonitorFeed();
    return NextResponse.json(feed, { headers: NO_STORE_HEADERS });
  } catch (e) {
    console.error("[monitor-feed] route error", e);
    return NextResponse.json({ error: "feed unavailable" }, { status: 500, headers: NO_STORE_HEADERS });
  }
}

