export default async function AdminAudit({
  searchParams,
}: {
  searchParams: Promise<{ staff?: string; action?: string }>;
}) {
  await requireArea("platform");
  const { staff, action } = await searchParams;

  // Either filter alone still fits comfortably under the old 200-row cap, but
  // combining them narrows the result set considerably — raising the cap to
  // 1000 when at least one filter is applied surfaces more real history for a
  // specific staff member / action instead of silently capping a query that's
  // already selective. The unfiltered view keeps the original 200-row cap.
  const rowCap = staff || action ? 1000 : 200;

  const where = {
    ...(staff ? { userId: staff } : {}),
    ...(action ? { action } : {}),
  };

  const [logs, staffUsers, distinctActions] = await Promise.all([
    db.auditLog.findMany({
      where: Object.keys(where).length > 0 ? where : undefined,
      include: { user: { select: { email: true, id: true } } },
      orderBy: { createdAt: "desc" },
      take: rowCap,
    }),
    // EMPLOYEE only (not SUPPORT/BILLING/ADMIN) — this filter exists specifically
    // to answer "what did this specific hire do", the question a per-employee
    // grant system (lib/staff-grants.ts) makes newly relevant.
    db.user.findMany({ where: { role: "EMPLOYEE" }, select: { id: true, email: true }, orderBy: { email: "asc" } }),
    // Real distinct action values straight from the table — never a hardcoded
    // list, so a newly introduced `audit()` call site shows up here automatically.
    db.auditLog.findMany({ distinct: ["action"], select: { action: true }, orderBy: { action: "asc" } }),
  ]);
  const actionOptions = distinctActions.map((a) => a.action);

