/* ------------------------------------------------------------------ *
 * Revenue chart — time-range toggle
 * ------------------------------------------------------------------ */

export type RevenueRange = "today" | "7d" | "14d" | "1m" | "all";

export const REVENUE_RANGES: { key: RevenueRange; label: string }[] = [
  { key: "today", label: "Today" },
  { key: "7d", label: "7 days" },
  { key: "14d", label: "14 days" },
  { key: "1m", label: "1 month" },
  { key: "all", label: "All time" },
];

export type RevenueSeriesResult = {
  series: number[];
  xLabels: string[];
  total: number;
  since: string;
  granularity: "hour" | "day" | "week" | "month";
};

function utcDayKey(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/** The real first revenue record ever posted for this account (not an arbitrary window). */
async function firstRevenueDate(): Promise<Date> {
  const first = await db.walletTransaction.findFirst({
    where: REVENUE_WHERE,
    orderBy: { createdAt: "asc" },
    select: { createdAt: true },
  });
  return first?.createdAt ?? new Date();
}

/** Start-of-bucket Date objects covering `[since, now]` at the given granularity. */
function bucketStarts(since: Date, now: Date, granularity: RevenueSeriesResult["granularity"]): Date[] {
  if (granularity === "month") {
    const starts: Date[] = [];
    const cur = new Date(Date.UTC(since.getUTCFullYear(), since.getUTCMonth(), 1));
    const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
    while (cur.getTime() <= end.getTime()) {
      starts.push(new Date(cur));
      cur.setUTCMonth(cur.getUTCMonth() + 1);
    }
    return starts;
  }
  const stepMs = granularity === "hour" ? 3600_000 : granularity === "day" ? 86400_000 : 7 * 86400_000;
  const starts: Date[] = [];
  let cur = new Date(since);
  while (cur.getTime() <= now.getTime()) {
    starts.push(new Date(cur));
    cur = new Date(cur.getTime() + stepMs);
  }
  if (starts.length === 0) starts.push(new Date(since));
  return starts;
}

/** Index of the last bucket whose start is `<= d` (bucket starts are sorted ascending). */
function bucketIndexFor(starts: Date[], d: Date): number {
  let lo = 0;
  let hi = starts.length - 1;
  let ans = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (starts[mid].getTime() <= d.getTime()) {
      ans = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return ans;
}

function bucketLabel(d: Date, granularity: RevenueSeriesResult["granularity"]): string {
  if (granularity === "hour") return `${String(d.getUTCHours()).padStart(2, "0")}:00`;
  if (granularity === "month") return d.toISOString().slice(0, 7);
  return utcDayKey(d).slice(5); // MM-DD
}

/**
 * Real revenue aggregation for the Operations Overview "Revenue" card, generalized
 * from the original hardcoded 14-day window to accept any `RevenueRange`. Every
 * range does a fresh DB query scoped to its own window — this is NOT the old
 * fixed 14-day dataset sliced client-side, so "Today" and "All time" both reflect
 * transactions the 14-day query would never have fetched in the first place.
 *
 * Bucketing granularity adapts to the span so the chart stays readable: hourly
 * for "Today", daily up to ~90 days, weekly up to ~18 months, monthly beyond
 * that (relevant mainly to "All time" on an older account).
 *
 * Same revenue definition as everywhere else in the console: `REVENUE_WHERE`
 * (orders/renewals/add-ons, refunds and affiliate payouts excluded) scoped to
 * revenue-counting accounts.
 */
export async function revenueSeriesForRange(range: RevenueRange): Promise<RevenueSeriesResult> {
  const now = new Date();
  let since: Date;
  switch (range) {
    case "today": {
      since = new Date(now);
      since.setUTCHours(0, 0, 0, 0);
      break;
    }
    case "7d":
      since = new Date(now.getTime() - 7 * 86400_000);
      break;
    case "14d":
      since = new Date(now.getTime() - 14 * 86400_000);
      break;
    case "1m":
      since = new Date(now.getTime() - 30 * 86400_000);
      break;
    case "all":
    default:
      since = await firstRevenueDate();
      break;
  }

  const spanDays = Math.max(0, (now.getTime() - since.getTime()) / 86400_000);
  const granularity: RevenueSeriesResult["granularity"] =
    range === "today" ? "hour" : spanDays <= 90 ? "day" : spanDays <= 548 ? "week" : "month";

  // Real DB aggregation scoped to this range's own window — every toggle re-queries
  // WalletTransaction, it never slices a dataset fetched for a different range.
  const tx = await db.walletTransaction.findMany({
    where: { ...REVENUE_WHERE, createdAt: { gte: since } },
    select: { amountCents: true, createdAt: true },
  });

  const starts = bucketStarts(since, now, granularity);
  const totals = new Array(starts.length).fill(0);
  for (const t of tx) {
    totals[bucketIndexFor(starts, t.createdAt)] += Math.abs(t.amountCents);
  }

  const series = totals.map((c) => c / 100);
  const total = series.reduce((a, b) => a + b, 0);
  const labels = starts.map((d) => bucketLabel(d, granularity));
  // First / middle / last labels only — matches the original 14-day chart's
  // 3-tick x-axis regardless of how many buckets this range produces.
  const xLabels =
    labels.length <= 1
      ? labels
      : [labels[0], labels[Math.floor((labels.length - 1) / 2)], labels[labels.length - 1]];

  return { series, xLabels, total, since: since.toISOString(), granularity };
}

