import { NextResponse } from "next/server";
import { realUser } from "@/lib/auth";
import { canAccess } from "@/lib/rbac";
import { revenueSeriesForRange, type RevenueRange } from "@/lib/admin-metrics";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const VALID_RANGES: RevenueRange[] = ["today", "7d", "14d", "1m", "all"];

/**
 * GET /api/admin/revenue-chart?range=today|7d|14d|1m|all
 *
 * Backs the time-range toggle on the Operations Overview "Revenue" card
 * (`<RevenueRangeChart/>`). Each call does a fresh, range-scoped
 * `WalletTransaction` aggregation via `revenueSeriesForRange` — the same
 * function the server-rendered 14-day default uses — so switching ranges
 * client-side never falls back to slicing a fixed dataset.
 *
 * Gated exactly like the page it lives on (`overview`, i.e. SUPPORT/BILLING/
 * ADMIN), never writes anything.
 */
export async function GET(req: Request) {
  const user = await realUser();
  if (!user || !canAccess(user.role, "overview")) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  const url = new URL(req.url);
  const rangeParam = url.searchParams.get("range");
  const range: RevenueRange = (VALID_RANGES as string[]).includes(rangeParam ?? "")
    ? (rangeParam as RevenueRange)
    : "14d";

  try {
    const data = await revenueSeriesForRange(range);
    return NextResponse.json(data, { headers: NO_STORE_HEADERS });
  } catch (e) {
    console.error("[revenue-chart] route error", e);
    return NextResponse.json({ error: "revenue chart unavailable" }, { status: 500, headers: NO_STORE_HEADERS });
  }
}

"use client";

import { useEffect, useState } from "react";
import { AreaChart } from "@/components/ui/charts";
import { REVENUE_RANGES, type RevenueRange } from "@/lib/admin-metrics";

/**
 * Client-side time-range toggle for the Operations Overview "Revenue" card.
 * Renders instantly with the server-rendered default range (`initialRange`,
 * fetched by app/admin/page.tsx via `revenueSeriesForRange` — no extra
 * request on first paint) and re-fetches `/api/admin/revenue-chart` — a real,
 * range-scoped DB aggregation, not a client-side slice of the initial
 * dataset — whenever a different range is picked.
 */
export function RevenueRangeChart({
  initialRange,
  initialSeries,
  initialXLabels,
  initialTotal,
}: {
  initialRange: RevenueRange;
  initialSeries: number[];
  initialXLabels: string[];
  initialTotal: number;
}) {
  const [range, setRange] = useState<RevenueRange>(initialRange);
  const [series, setSeries] = useState(initialSeries);
  const [xLabels, setXLabels] = useState(initialXLabels);
  const [total, setTotal] = useState(initialTotal);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (range === initialRange) {
      // Back to the range the server already rendered — just restore it,
      // no need to re-fetch what we already have.
      setSeries(initialSeries);
      setXLabels(initialXLabels);
      setTotal(initialTotal);
      setError(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(false);
    fetch(`/api/admin/revenue-chart?range=${range}`, { cache: "no-store" })
      .then((r) => {
        if (!r.ok) throw new Error("bad response");
        return r.json();
      })
      .then((data: { series: number[]; xLabels: string[]; total: number }) => {
        if (cancelled) return;
        setSeries(data.series);
        setXLabels(data.xLabels);
        setTotal(data.total);
      })
      .catch(() => {
        if (!cancelled) setError(true);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [range]);

  const activeLabel = REVENUE_RANGES.find((r) => r.key === range)?.label ?? "14 days";

  return (
    <div className="card">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <h2 className="font-semibold">Revenue · {activeLabel.toLowerCase()}</h2>
        <span className="text-sm font-semibold text-emerald-400">${total.toFixed(2)}</span>
      </div>
      <p className="mb-2 text-xs text-slate-500">
        Orders, renewals and add-ons — refunds and affiliate payouts excluded.
      </p>
      <div className="mb-3 flex flex-wrap gap-1.5">
        {REVENUE_RANGES.map((r) => (
          <button
            key={r.key}
            type="button"
            onClick={() => setRange(r.key)}
            disabled={loading && range === r.key}
            className={`rounded-lg border px-2.5 py-1 text-xs font-medium transition ${
              range === r.key
                ? "border-brand-400/30 bg-brand-500/10 text-brand-200"
                : "border-white/10 text-slate-400 hover:bg-white/[0.06]"
            }`}
          >
            {r.label}
          </button>
        ))}
      </div>
      {error ? (
        <p className="py-6 text-sm text-slate-500">Could not load revenue for this range.</p>
      ) : (
        <div className={loading ? "opacity-50 transition-opacity" : "transition-opacity"}>
          <AreaChart
            id="rev-range"
            series={[{ name: "Revenue $", data: series, color: "#34d399" }]}
            height={180}
            yLabel={(v) => `$${v.toFixed(0)}`}
            xLabels={xLabels}
          />
        </div>
      )}
    </div>
  );
}

