  /** Staff-set kill switch for the AI assistant on this one thread (see `toggleAiPaused`). */
  aiPaused: boolean;
  messages: InboxMessage[];
};

/**
 * Resolve staff user ids to display names in one query. Not a "use server"
 * export (it takes non-serializable args and isn't called from the client);
 * used internally to attach `assignedToName` to inbox payloads so the admin
 * thread view can label each human reply with the agent handling it.
 */
async function resolveStaffNames(
  ids: (string | null)[]
): Promise<Map<string, string>> {
  const unique = Array.from(new Set(ids.filter((v): v is string => !!v)));
  if (unique.length === 0) return new Map();
  const users = await db.user.findMany({
    where: { id: { in: unique } },
    select: { id: true, name: true },
  });
  return new Map(users.map((u) => [u.id, u.name]));
}

